begin;create extension if not exists pgtap with schema extensions;select extensions.plan(29);
select extensions.has_table('public','twitter_analytics_jobs','jobs manuais existem');select extensions.has_table('public','twitter_analytics_snapshots','snapshots locais existem');select extensions.ok(not has_function_privilege('authenticated','public.twitter_confirm_analytics_job(uuid,uuid,text,text,integer,jsonb,jsonb)','EXECUTE'),'cliente não reserva analytics diretamente');
insert into auth.users(id,instance_id,aud,role,email,encrypted_password,email_confirmed_at,created_at,updated_at)values('13500000-0000-4000-8000-000000000001','00000000-0000-0000-0000-000000000000','authenticated','authenticated','twitter-235@example.com','',now(),now(),now());insert into public.organizations(id,name,slug,created_by)values('23500000-0000-4000-8000-000000000001','Twitter 235','twitter-235','13500000-0000-4000-8000-000000000001');insert into public.organization_members(organization_id,user_id,role,invited_by)values('23500000-0000-4000-8000-000000000001','13500000-0000-4000-8000-000000000001','admin','13500000-0000-4000-8000-000000000001');
create temporary table t235(identity_id uuid,connection_id uuid,profile_id uuid,epoch_id uuid,program_id uuid,reservation_id uuid,item_id uuid,wallet_version bigint)on commit drop;grant select,insert,update on t235 to service_role;insert into t235 default values;set local role service_role;select set_config('request.jwt.claim.role','service_role',true);
do $$declare identity jsonb;connection jsonb;profile jsonb;reservation jsonb;pid uuid:=gen_random_uuid();iid uuid:=gen_random_uuid();begin identity:=public.twitter_register_identity_and_grant('23500000-0000-4000-8000-000000000001','zernio-235');connection:=public.twitter_upsert_connection_credentials('23500000-0000-4000-8000-000000000001',(identity->>'identityId')::uuid,'C','zp-235',repeat('encrypted',5),repeat('e',64),'api','scope','13500000-0000-4000-8000-000000000001','twitter-235@example.com');profile:=public.twitter_sync_profile_from_zernio('23500000-0000-4000-8000-000000000001',(connection->>'connectionId')::uuid,'za-235','xu-235','perfil235','Perfil',null,true,true,true,false,'free','[]');insert into public.twitter_programs(id,organization_id,schedule_kind,starts_at,ends_at,interval_minutes,total_requested,funded_count,unfunded_count,reserved_micros,rate_card_id,rate_card_version,review_digest,idempotency_key,created_by)select pid,'23500000-0000-4000-8000-000000000001','interval',now(),now(),1,1,1,0,15000,id,version,repeat('d',64),'program-235','13500000-0000-4000-8000-000000000001'from public.twitter_rate_cards where active;reservation:=public.twitter_create_wallet_reservation('23500000-0000-4000-8000-000000000001',(identity->>'identityId')::uuid,(connection->>'connectionId')::uuid,1,'post_dm_create','publication',pid,15000,1,'reservation-235');insert into public.twitter_program_reservations values(pid,(reservation->>'reservationId')::uuid,(identity->>'identityId')::uuid,'post_dm_create');insert into public.twitter_publication_items(id,organization_id,program_id,profile_id,connection_epoch_id,connection_id,identity_id,slot_index,execute_at,content,weighted_characters,category,amount_micros,status,idempotency_key)values(iid,'23500000-0000-4000-8000-000000000001',pid,(profile->>'profileId')::uuid,(profile->>'epochId')::uuid,(connection->>'connectionId')::uuid,(identity->>'identityId')::uuid,0,now(),'publicado',9,'post_dm_create',15000,'published','item-235');insert into public.twitter_publication_attempts(organization_id,item_id,attempt_number,worker_id,idempotency_key,status,post_id,finished_at)values('23500000-0000-4000-8000-000000000001',iid,1,'test','attempt-235','published','zpost-235',now());update t235 set identity_id=(identity->>'identityId')::uuid,connection_id=(connection->>'connectionId')::uuid,profile_id=(profile->>'profileId')::uuid,epoch_id=(profile->>'epochId')::uuid,program_id=pid,reservation_id=(reservation->>'reservationId')::uuid,item_id=iid,wallet_version=(select version from public.twitter_wallets where identity_id=(identity->>'identityId')::uuid);end$$;
select public.twitter_confirm_analytics_job('23500000-0000-4000-8000-000000000001','13500000-0000-4000-8000-000000000001','analytics-job-235',repeat('e',64),1,(select jsonb_build_array(jsonb_build_object('identityId',identity_id,'walletVersion',wallet_version))from t235),(select jsonb_build_array(jsonb_build_object('type','post','id',item_id),jsonb_build_object('type','profile','id',profile_id))from t235));
select extensions.is((select resource_count from public.twitter_analytics_jobs),2,'job contém os dois recursos');select extensions.is((select reserved_micros from public.twitter_analytics_jobs),55000::bigint,'reserva máxima usa 9x5k + 10k');select extensions.is((select count(*)::bigint from public.twitter_analytics_items),2::bigint,'itens foram materializados');select extensions.is((select count(*)::bigint from public.twitter_analytics_job_reservations),2::bigint,'reservas separadas por categoria');select extensions.is((select reserved_micros from public.twitter_wallets where identity_id=(select identity_id from t235)),70000::bigint,'analytics preserva reserva de publicação');select extensions.is((select posted_balance_micros from public.twitter_wallets where identity_id=(select identity_id from t235)),12000000::bigint,'confirmar não debita antes da leitura');select extensions.is((select count(*)::bigint from public.twitter_wallet_ledger where entry_kind='debit'),0::bigint,'nenhum débito sem resultado');
select public.twitter_confirm_analytics_job('23500000-0000-4000-8000-000000000001','13500000-0000-4000-8000-000000000001','analytics-job-235',repeat('e',64),1,'[]','[]');select extensions.is((select count(*)::bigint from public.twitter_analytics_jobs),1::bigint,'replay não duplica job');
create temporary table c235a as select * from public.twitter_claim_analytics_items('analytics-worker-235',10);grant select on c235a to service_role;select extensions.is((select count(*)::bigint from c235a),1::bigint,'apenas uma leitura ativa por conexão');select public.twitter_complete_analytics_item((select attempt_id from c235a),'succeeded','analytics-success-235','{"impressions":10}',now(),200,'ok','req-a',null,'{}',(select case when resource_type='post' then 3 else 1 end from c235a));select extensions.is((select count(*)::bigint from public.twitter_analytics_snapshots),1::bigint,'sucesso cria snapshot local');select extensions.is((select count(*)::bigint from public.twitter_wallet_ledger where entry_kind='debit'),1::bigint,'sucesso liquida somente seu recurso');select extensions.is((select i.settled_units from public.twitter_analytics_items i join c235a c on c.item_id=i.id),(select case when resource_type='post' then 3 else 1 end from c235a),'registra somente unidades comprovadas');select extensions.is((select i.released_micros from public.twitter_analytics_items i join c235a c on c.item_id=i.id),(select i.amount_micros-i.unit_cost_micros*i.settled_units from public.twitter_analytics_items i join c235a c on c.item_id=i.id),'libera excedente da reserva do item');select extensions.is((select e.amount_micros from public.twitter_analytics_result_events e where e.idempotency_key='analytics-success-235'),(select i.unit_cost_micros*i.settled_units from public.twitter_analytics_items i join c235a c on c.item_id=i.id),'evento registra débito real, não reserva máxima');select public.twitter_complete_analytics_item((select attempt_id from c235a),'succeeded','analytics-success-235','{}',now(),200,'ok','req-a',null,'{}',(select case when resource_type='post' then 3 else 1 end from c235a));select extensions.is((select count(*)::bigint from public.twitter_wallet_ledger where entry_kind='debit'),1::bigint,'replay não duplica débito');
select extensions.throws_ok((select format($q$select public.twitter_complete_analytics_item('%s','succeeded','analytics-different-key-235','{}',now(),200,'ok',null,null,'{}',%s)$q$,attempt_id,case when resource_type='post' then 3 else 1 end)from c235a),'55000','Item de analytics já possui resultado terminal.','chave diferente não liquida item terminal novamente');
create temporary table c235b as select * from public.twitter_claim_analytics_items('analytics-worker-235',10);grant select on c235b to service_role;select extensions.is((select count(*)::bigint from c235b),1::bigint,'segundo recurso só é claimed após o primeiro');select public.twitter_complete_analytics_item((select attempt_id from c235b),'failed','analytics-failed-235','{}',null,400,'confirmed','req-b','falha sem cobrança','{}',null);select extensions.is((select reserved_micros from public.twitter_wallets where identity_id=(select identity_id from t235)),15000::bigint,'falha confirmada libera apenas analytics restante');select extensions.is((select status::text from public.twitter_analytics_jobs),'partially_succeeded','job registra sucesso parcial');select extensions.throws_ok($$update public.twitter_analytics_result_events set resolution='failed'$$,'55000','Registro financeiro imutável.','resultado de analytics é imutável');
update t235 set wallet_version=(select version from public.twitter_wallets where identity_id=t235.identity_id);select public.twitter_confirm_analytics_job('23500000-0000-4000-8000-000000000001','13500000-0000-4000-8000-000000000001','analytics-unknown-235',repeat('a',64),1,(select jsonb_build_array(jsonb_build_object('identityId',identity_id,'walletVersion',wallet_version))from t235),(select jsonb_build_array(jsonb_build_object('type','profile','id',profile_id))from t235));create temporary table c235c as select * from public.twitter_claim_analytics_items('analytics-worker-235',1);grant select on c235c to service_role;select public.twitter_complete_analytics_item((select attempt_id from c235c),'outcome_unknown','analytics-unknown-result-235','{}',null,503,'timeout','req-c','incerto','{}',null);select extensions.is((select reserved_micros from public.twitter_wallets where identity_id=(select identity_id from t235)),25000::bigint,'resultado incerto mantém hold');select extensions.is((select status::text from public.twitter_analytics_jobs where id=(select job_id from c235c)),'outcome_unknown','job incerto exige reconciliação');select extensions.is((select count(*)::bigint from public.twitter_analytics_snapshots),1::bigint,'incerto não cria snapshot');
update public.twitter_wallets set posted_balance_micros=5025000 where identity_id=(select identity_id from t235);update t235 set wallet_version=(select version from public.twitter_wallets where identity_id=t235.identity_id);
select extensions.throws_ok((select format($q$select public.twitter_confirm_analytics_job('23500000-0000-4000-8000-000000000001','13500000-0000-4000-8000-000000000001','analytics-floor-235','%s',1,'%s','%s')$q$,repeat('f',64),jsonb_build_array(jsonb_build_object('identityId',identity_id,'walletVersion',wallet_version))::text,jsonb_build_array(jsonb_build_object('type','profile','id',profile_id))::text)from t235),'P0001','Piso protegido de US$ 5,00 impede esta análise.','piso de US$ 5 bloqueia análise');
select extensions.is((select count(*)::bigint from public.twitter_analytics_jobs),2::bigint,'falha do piso não deixa job parcial');select extensions.is((select count(*)::bigint from pg_constraint c join pg_class t on t.oid=c.conrelid join pg_class f on f.oid=c.confrelid where t.relname like 'twitter_%'and f.relname in('instagram_profiles','publication_items')),0::bigint,'analytics não referencia Instagram');
select jsonb_build_object('finish',(select jsonb_agg(v)from extensions.finish()v),'jobs',(select count(*)from public.twitter_analytics_jobs),'reserved',(select reserved_micros from public.twitter_wallets where identity_id=(select identity_id from t235)))diagnostics;rollback;
